"""Remote execution.

Secret: the syntax of ``ssh`` connection strings, how each transport
(ssh, docker, docker-compose, docker-compose-run, vagrant) builds its
command line, how the remote appctl command is assembled (pre-command,
working directory, forwarded arguments) and how transport failures are
reported.
"""

import re
import shlex
import shutil
import subprocess

from . import messages as _messages

_REMOTE_BINARY = "appctl"
_PRE_CMD_ENV = "APPCTL_SSH_PRE_CMD"
_STRICT_ENV = "APPCTL_STRICT_ARGS_MODE"
_CONNECT_FAILURE = 255
_SSH_URL = re.compile(
    r"^((?P<scheme>docker|docker-compose|docker-compose-run|ssh|vagrant):)?"
    r"(//)?((?P<user>[^@:]+)@)?(?P<host>[^:/~]+)(:(?P<port>\d*))?"
    r"(?P<path>[/~].*)?$")
# Connection keys forwarded to the remote invocation as runtime flags.
_FORWARDED = ("path", "url", "user")


def parse(url):
    """Split a connection string into its parts (missing parts are None)."""
    match = _SSH_URL.match(url or "")
    if not match:
        return {"scheme": None, "user": None, "host": url, "port": None, "path": None}
    bits = match.groupdict()
    return {key: (value or None) for key, value in bits.items()}


def _quote_path(path):
    if path == "~":
        return path
    if path.startswith("~/"):
        return "~/" + shlex.quote(path[2:])
    return shlex.quote(path)


def remote_command(args, bits, env):
    """The shell command run on the remote side."""
    parts = []
    pre = (env.get(_PRE_CMD_ENV) or "").strip().rstrip(";").strip()
    if pre:
        parts.append(pre + ";")
    if bits.get("path"):
        parts.append(f"cd {_quote_path(bits['path'])};")
    if env.get(_STRICT_ENV):
        parts.append(f"{_STRICT_ENV}=1")
    parts.append(_REMOTE_BINARY)
    parts.extend(shlex.quote(a) for a in args)
    return " ".join(parts)


def transport_argv(bits, command, args, tty, debug):
    """The local command line that runs ``command`` remotely."""
    scheme = bits.get("scheme") or "ssh"
    host, user, port = bits.get("host") or "", bits.get("user"), bits.get("port")
    if scheme == "docker":
        argv = ["docker", "exec"]
        if user:
            argv += ["--user", user]
        if tty:
            argv.append("-t")
        return argv + [host, "sh", "-c", command]
    if scheme == "docker-compose":
        argv = ["docker-compose", "exec"]
        if user:
            argv += ["--user", user]
        if not tty:
            argv.append("-T")
        return argv + [host, "sh", "-c", command]
    if scheme == "docker-compose-run":
        argv = ["docker-compose", "run"]
        if user:
            argv += ["--user", user]
        if not tty:
            argv.append("-T")
        return argv + [host] + list(args)
    if scheme == "vagrant":
        return ["vagrant", "ssh", "-c", command, host]
    argv = ["ssh"]
    if port:
        argv += ["-p", str(int(port))]
    argv.append("-t" if tty else "-T")
    argv.append("-vvv" if debug else "-q")
    argv.append(f"{user}@{host}" if user else host)
    return argv + [command]


def _fileno(stream):
    try:
        return stream.fileno()
    except (AttributeError, OSError, ValueError):
        return None


def _isatty(stream):
    try:
        return stream.isatty()
    except (AttributeError, ValueError):
        return False


def forwarded_args(raw_args, connection, runtime_values):
    """Arguments for the remote appctl: the local ones minus ``--ssh``, plus
    connection parameters that were not given at runtime."""
    args = [a for a in raw_args if not (a == "--ssh" or a.startswith("--ssh="))]
    for key in _FORWARDED:
        value = connection.get(key)
        if value not in (None, "") and key not in runtime_values:
            args.append(f"--{key}={value}")
    return args


def run(ssh, raw_args, connection, runtime_values, config, env, out, stdout, stderr):
    """Run the command through the configured transport; return exit code."""
    bits = parse(ssh)
    args = forwarded_args(raw_args, connection, runtime_values)
    tty = not config.get("skip-tty") and _isatty(stdout)
    command = remote_command(args, bits, env)
    argv = transport_argv(bits, command, args, tty, config.debug())
    out.debug(f"Running remote command: {shlex.join(argv)}", group="ssh")
    for stream in (stdout, stderr):
        if hasattr(stream, "flush"):
            stream.flush()
    executable = shutil.which(argv[0], path=env.get("PATH"))
    if executable is None:
        out.error(_messages.ssh_connection_failed())
        return _CONNECT_FAILURE
    out_fd, err_fd = _fileno(stdout), _fileno(stderr)
    try:
        proc = subprocess.run(
            [executable] + argv[1:], env=dict(env),
            stdout=out_fd if out_fd is not None else subprocess.PIPE,
            stderr=err_fd if err_fd is not None else subprocess.PIPE)
    except OSError:
        out.error(_messages.ssh_connection_failed())
        return _CONNECT_FAILURE
    if out_fd is None and proc.stdout:
        stdout.write(proc.stdout.decode(errors="replace"))
    if err_fd is None and proc.stderr:
        stderr.write(proc.stderr.decode(errors="replace"))
    if proc.returncode == _CONNECT_FAILURE:
        out.error(_messages.ssh_connection_failed())
    return proc.returncode
"""Configuration sources.

Secret: where the global and project config files live, how YAML
inheritance (``_: {inherit, merge}``) and array merging work, how alias
definitions are collected from files, and how missing global defaults are
written back to the global config file.
"""

import errno
import os

from . import config_spec, messages, yaml_lite
from .aliases import is_alias_name
from .errors import CliError

_PROJECT_FILES = ("appctl.local.yml", "appctl.yml")
_AUTO_DEFAULTS = (("locale", "en_US"), ("installer_version", "stable"))
_META_KEY = "_"


class Locations:
    """Filesystem locations derived from the environment."""

    def __init__(self, env):
        root = env.get("APPCTL_ROOT_DIR") or ""
        config = env.get("APPCTL_CONFIG_PATH") or ""
        self.explicit = bool(root or config)
        if not root:
            home = env.get("HOME") or os.path.expanduser("~")
            root = os.path.join(home, ".appctl")
        self.root_dir = _clean(root)
        self.global_config_path = (_clean(config) if config else
                                   os.path.join(self.root_dir, "config", "config.yml"))
        packages = env.get("APPCTL_PACKAGES_DIR") or ""
        self.packages_dir = (_clean(packages) if packages else
                             os.path.join(self.root_dir, "packages"))


def _clean(path):
    path = os.path.expanduser(path)
    stripped = path.rstrip(os.sep)
    return stripped or path


def find_project_config(cwd):
    """Search upward from ``cwd`` for a project config file."""
    directory = os.path.abspath(cwd)
    while True:
        for name in _PROJECT_FILES:
            candidate = os.path.join(directory, name)
            if os.path.isfile(candidate):
                return candidate
        parent = os.path.dirname(directory)
        if parent == directory:
            return None
        directory = parent


def _absolutize(path, base):
    path = os.path.expanduser(path)
    if os.path.isabs(path):
        return path
    return os.path.normpath(os.path.join(base, path))


def _arrayify(value):
    if value is None:
        return []
    if isinstance(value, (list, tuple)):
        return list(value)
    return [value]


def _combine(old, new, merge):
    if merge and isinstance(old, list) and isinstance(new, list):
        return old + new
    return new


def _parse(path, text):
    try:
        data = yaml_lite.load(text)
    except yaml_lite.YamlError as exc:
        raise CliError(messages.config_unparsable(path, exc)) from None
    return data if isinstance(data, dict) else ({} if data is None else None)


def _read(path, tolerant=False):
    """Return the mapping stored at ``path`` or ``None`` if absent."""
    if not os.path.exists(path):
        return None
    try:
        with open(path, encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        if tolerant:
            return None
        raise CliError(messages.config_unreadable(path, exc)) from None
    data = _parse(path, text)
    return {} if data is None else data


class LoadedConfig:
    """Values, aliases and other keys collected from config files."""

    def __init__(self):
        self.values = {}
        self.aliases = {}
        self.extra = {}
        self.global_config_path = None
        self.project_config_path = None
        self.files = []

    def merge_file(self, path, tolerant=False, chain=()):
        real = os.path.realpath(path)
        if real in chain:
            return
        data = _read(path, tolerant)
        if data is None:
            return
        meta = data.get(_META_KEY)
        meta = meta if isinstance(meta, dict) else {}
        base = os.path.dirname(os.path.abspath(path))
        inherit = meta.get("inherit")
        if isinstance(inherit, str) and inherit:
            self.merge_file(_inherit_path(inherit, base), tolerant, chain + (real,))
        merge = bool(meta.get("merge"))
        self.files.append(path)
        for key, value in data.items():
            if key == _META_KEY:
                continue
            key = str(key)
            if is_alias_name(key):
                self._merge_alias(key, value, base, merge)
            elif config_spec.file_param(key) is not None:
                self._merge_param(key, value, base, merge)
            else:
                self.extra[key] = _combine(self.extra.get(key), value, merge)

    def _merge_alias(self, name, value, base, merge):
        if isinstance(value, list):
            definition = [str(v) for v in value if v is not None]
        elif isinstance(value, dict):
            definition = {str(k): v for k, v in value.items()}
            path = definition.get("path")
            if isinstance(path, str) and path and "ssh" not in definition:
                definition["path"] = _absolutize(path, base)
        elif value is None:
            definition = {}
        else:
            return
        self.aliases[name] = _combine(self.aliases.get(name), definition, merge)

    def _merge_param(self, key, value, base, merge):
        param = config_spec.file_param(key)
        if param.kind == "list":
            value = _arrayify(value)
        if key == "path" and isinstance(value, str) and value:
            value = _absolutize(value, base)
        self.values[key] = _combine(self.values.get(key), value, merge)


def _inherit_path(inherit, base):
    inherit = os.path.expanduser(inherit)
    if os.path.isabs(inherit):
        return inherit
    relative = os.path.join(base, inherit)
    if not os.path.exists(relative) and os.path.exists(inherit):
        return os.path.abspath(inherit)
    return os.path.normpath(relative)


def ensure_global_defaults(locations):
    """Write missing auto-created keys into the global config file."""
    path = locations.global_config_path
    try:
        text = ""
        if os.path.exists(path):
            if not os.path.isfile(path):
                raise IsADirectoryError(errno.EISDIR, os.strerror(errno.EISDIR), path)
            with open(path, encoding="utf-8") as handle:
                text = handle.read()
        data = _parse(path, text)
        if data is None:
            return
        missing = [(k, v) for k, v in _AUTO_DEFAULTS if k not in data]
        if not missing:
            return
        expected = dict(data, **dict(missing))
        separator = "\n" if text and not text.endswith("\n") else ""
        updated = text + separator + "".join(
            yaml_lite.scalar_line(k, v) for k, v in missing)
        try:
            if yaml_lite.load(updated) != expected:
                raise yaml_lite.YamlError("append changed meaning")
        except yaml_lite.YamlError:
            updated = yaml_lite.dump(expected)
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(updated)
    except OSError as exc:
        if locations.explicit:
            raise CliError(messages.config_unwritable(path, exc)) from None


def load(locations, cwd):
    """Load the global config file then the project config file."""
    loaded = LoadedConfig()
    ensure_global_defaults(locations)
    global_path = locations.global_config_path
    if os.path.isfile(global_path):
        loaded.global_config_path = global_path
        loaded.merge_file(global_path, tolerant=not locations.explicit)
    project = find_project_config(cwd)
    if project and not (loaded.global_config_path and
                        os.path.realpath(project) == os.path.realpath(global_path)):
        loaded.project_config_path = project
        loaded.merge_file(project)
    return loaded
"""Global parameter specification.

Secret: which global parameters exist, whether each may be given as a
runtime flag and/or in a config file, their defaults, runtime syntax, and
which are deprecated or hidden.
"""

from .synopsis import Synopsis


class Param:
    __slots__ = ("name", "runtime", "file", "default", "kind", "deprecated",
                 "hidden", "description")

    def __init__(self, name, *, runtime=None, file=True, default=None,
                 kind="value", deprecated=False, hidden=False, description=""):
        self.name = name
        self.runtime = runtime        # synopsis fragment, or None
        self.file = file
        self.default = default
        self.kind = kind              # "value", "list" or "bool"
        self.deprecated = deprecated
        self.hidden = hidden
        self.description = description


_PARAMS = [
    Param("path", runtime="[--path=<path>]",
          description="Path to the application files."),
    Param("url", runtime="[--url=<url>]",
          description="Pretend request came from given URL."),
    Param("user", runtime="[--user=<id>]",
          description="Set the user."),
    Param("ssh", runtime="[--ssh=<ssh>]",
          description="Perform operation against a remote server over SSH "
                      "(or a container using scheme of \"docker\", "
                      "\"docker-compose\", \"docker-compose-run\", \"vagrant\")."),
    Param("disabled_commands", default=[], kind="list",
          description="(Sub)commands to disable."),
    Param("projects_path", description="Directory in which projects are stored."),
    Param("locale", default="en_US", description="Locale to use."),
    Param("cert-email", description="E-mail address used for certificates."),
    Param("env", description="Environment name."),
    Param("admin-email", description="Administrator e-mail address."),
    Param("sysctl", description="Kernel parameters to apply."),
    Param("skip-tty", default=False, kind="bool",
          description="Do not allocate a TTY for remote commands."),
    Param("custom-compose", description="Custom compose file."),
    Param("installer_version", default="stable",
          description="Installer release channel."),
    Param("color", runtime="[--[no-]color]", default="auto",
          description="Whether to colorize the output."),
    Param("debug", runtime="[--debug[=<group>]]", file=False, default=False,
          description="Show all errors and add verbosity to bootstrap."),
    Param("quiet", runtime="[--quiet]", file=False, default=False,
          kind="bool", description="Suppress informational messages."),
]

_BY_NAME = {p.name: p for p in _PARAMS}


def params():
    return list(_PARAMS)


def get(name):
    return _BY_NAME.get(name)


def defaults():
    return {p.name: (list(p.default) if isinstance(p.default, list) else p.default)
            for p in _PARAMS}


def file_param(name):
    """The parameter named ``name`` if it may be set from a config file."""
    param = _BY_NAME.get(name)
    return param if param is not None and param.file else None


def runtime_synopsis():
    return Synopsis(" ".join(p.runtime for p in _PARAMS if p.runtime))


def is_deprecated(name):
    param = _BY_NAME.get(name)
    return bool(param and param.deprecated)


def visible():
    """Parameters that may be shown in help output."""
    return [p for p in _PARAMS if not p.hidden]
"""Argument validation and binding.

Secret: the order in which argument checks run, which conditions count as
errors, how associative-argument errors are batched, and when defaults are
filled in.
"""

from . import messages as _messages
from .errors import CliError, MissingPositional
from .suggest import suggest
from .synopsis import Synopsis


class BoundArguments:
    """Validated arguments with defaults applied."""

    def __init__(self, positionals, options):
        self._positionals = list(positionals)
        self._options = dict(options)

    @property
    def positionals(self):
        return list(self._positionals)

    def positional(self, index, default=None):
        if index < len(self._positionals):
            return self._positionals[index]
        return default

    def option(self, name, default=None):
        return self._options.get(name, default)

    def has_option(self, name):
        return name in self._options

    def options(self):
        return dict(self._options)


def _check_positionals(synopsis, words):
    if len(words) < synopsis.required_positional_count():
        raise MissingPositional()
    limit = synopsis.positional_limit()
    if limit is not None and len(words) > limit:
        raise CliError(_messages.too_many_positionals(words[limit:]))


def _bind_options(synopsis, options):
    bound = {}
    needs_value, takes_no_value, unknown = [], [], []
    for name, value in options:
        key, interpreted, status = synopsis.interpret(name, value)
        if status == Synopsis.OK:
            bound[key] = interpreted
        elif status == Synopsis.NEEDS_VALUE:
            bound.pop(key, None)
            needs_value.append(key)
        elif status == Synopsis.TAKES_NO_VALUE:
            takes_no_value.append(key)
        elif name not in unknown:
            unknown.append(name)

    required = synopsis.required_option_names()
    errors = [_messages.missing_parameter(key)
              for key in required if key not in bound]
    errors += [_messages.parameter_needs_value(key)
               for key in dict.fromkeys(needs_value)
               if key not in required and key not in bound]
    errors += [_messages.parameter_takes_no_value(key)
               for key in dict.fromkeys(takes_no_value)]
    generic = synopsis.requires_generic_option()
    if generic and not any(k not in synopsis.option_names() for k in bound):
        errors.append(_messages.missing_parameter(generic))
    known = synopsis.option_names()
    errors += [_messages.unknown_parameter(key, suggest(key, known))
               for key in unknown]
    if errors:
        raise CliError(_messages.parameter_errors(errors))
    return bound


def _apply_defaults(synopsis, words, options, defaults):
    words = list(words)
    names = synopsis.positional_names()
    for name in names[len(words):]:
        if name not in defaults:
            break
        words.append(defaults[name])
    for name in synopsis.option_names():
        if name not in options and name in defaults:
            options[name] = defaults[name]
    return words, options


def bind(path, synopsis, defaults, words, options):
    """Validate ``words`` and ``options`` against ``synopsis``.

    ``options`` is a sequence of ``(name, value)`` pairs where ``value`` is a
    string or ``None`` (no ``=`` given). Raises ``MissingPositional`` when
    required positionals are absent and ``CliError`` for other problems.
    """
    malformed = synopsis.malformed_parts()
    if malformed:
        raise CliError(_messages.invalid_synopsis(path, malformed))
    _check_positionals(synopsis, list(words))
    bound = _bind_options(synopsis, options)
    words, bound = _apply_defaults(synopsis, words, bound, dict(defaults))
    return BoundArguments(words, bound)
"""Command storage.

Secret: how commands are stored as a tree, how names and aliases are
matched, and how children are ordered for display.
"""

from .synopsis import Synopsis


def _sort_key(name):
    return (name.casefold(), name)


class CommandNode:
    """One command (or the root) in the command tree."""

    def __init__(self, name, parent=None):
        self._name = name
        self._parent = parent
        self._children = {}
        self._aliases = {}
        self._handler = None
        self._synopsis_text = ""
        self._synopsis = Synopsis("")
        self._description = ""
        self._alias = None
        self._defaults = {}

    def _configure(self, handler, synopsis, description, alias, defaults):
        self._handler = handler
        self._synopsis_text = synopsis or ""
        self._synopsis = Synopsis(self._synopsis_text)
        self._description = description or ""
        self._alias = alias
        self._defaults = dict(defaults or {})

    @property
    def name(self):
        return self._name

    @property
    def path(self):
        """Full space-separated command path ('' for the root)."""
        words = []
        node = self
        while node._parent is not None:
            words.append(node._name)
            node = node._parent
        return " ".join(reversed(words))

    @property
    def parent(self):
        return self._parent

    @property
    def description(self):
        return self._description

    @property
    def alias(self):
        return self._alias

    @property
    def synopsis(self):
        return self._synopsis

    def defaults(self):
        return dict(self._defaults)

    def is_root(self):
        return self._parent is None

    def is_runnable(self):
        return self._handler is not None

    def has_children(self):
        return bool(self._children)

    def children(self):
        return [self._children[n] for n in sorted(self._children, key=_sort_key)]

    def child_names(self):
        return sorted(self._children, key=_sort_key)

    def find_child(self, word):
        """Match ``word`` against child names, then child aliases."""
        if word in self._children:
            return self._children[word]
        canonical = self._aliases.get(word)
        return self._children.get(canonical) if canonical else None

    def run(self, context):
        return self._handler(context)

    def _child(self, name, create):
        if name not in self._children and create:
            if name in self._aliases:
                raise ValueError(f"'{name}' is already an alias under '{self.path}'")
            self._children[name] = CommandNode(name, self)
        return self._children.get(name)

    def _add_alias(self, alias, canonical):
        if alias in self._children or self._aliases.get(alias, canonical) != canonical:
            raise ValueError(f"alias '{alias}' conflicts under '{self.path}'")
        self._aliases[alias] = canonical


class CommandTree:
    """Registry of all commands."""

    def __init__(self):
        self._root = CommandNode("")

    @property
    def root(self):
        return self._root

    def register(self, path, handler=None, *, synopsis="", description="",
                 alias=None, defaults=None):
        """Register (or update) the command at space-separated ``path``.

        Missing parent commands are created as non-runnable groups.
        """
        words = path.split()
        if not words:
            raise ValueError("command path must not be empty")
        node = self._root
        for word in words:
            node = node._child(word, create=True)
        node._configure(handler, synopsis, description, alias, defaults)
        if alias:
            node.parent._add_alias(alias, node.name)
        return node

    def find(self, words):
        """Return the node at exactly ``words`` (aliases allowed) or ``None``."""
        node = self._root
        for word in words:
            node = node.find_child(word)
            if node is None:
                return None
        return None if node is self._root else node

